<script lang="ts">
  import guide from "../../../docs/IMPLEMENTATION.md?raw";
  import {
    cameraSimulationExamples,
    createScannerExamples,
    type ScannerDialogExampleName,
    type ScannerExampleName,
  } from "../../../examples/scanner-examples";
  import type { ScannerState, StatusTone } from "../../../src/core/types";
  import type { SvelteScannerRuntime } from "../../src/runtime/scanner-runtime";
  import StateInspector from "./StateInspector.svelte";

  let {
    runtime,
    scannerState,
    events,
    onRecreate,
    onDevice,
    onOrientation,
    onSafeArea,
    onTheme,
    onClearEvents,
  }: {
    runtime: SvelteScannerRuntime<unknown>;
    scannerState: Readonly<ScannerState<unknown>>;
    events: readonly { time: string; type: string; detail: string }[];
    onRecreate(): void;
    onDevice(value: string): void;
    onOrientation(value: string): void;
    onSafeArea(value: boolean): void;
    onTheme(name: string, value: string): void;
    onClearEvents(): void;
  } = $props();

  let payload = $state("CYBERIA-MODULUS / SEEK-QR / SVELTE");
  let statusText = $state("Host-controlled scanner status");
  let dialogTitle = $state("Host confirmation");
  let dialogBody = $state("The Svelte surface displays this message but does not understand its policy.");
  let dialogOutput = $state("resolved action / —");
  let cameraFeedStatus = $state("requesting camera access");
  let cameras = $state<readonly MediaDeviceInfo[]>([]);
  let device = $state("phone");
  let orientation = $state("portrait");
  const examples = $derived(createScannerExamples(runtime));

  async function emit() { await runtime.emitSynthetic(payload); }
  async function enumerate() { cameras = await runtime.enumerateCameras(); }
  async function startCamera() {
    cameraFeedStatus = "requesting camera access";
    await runtime.startCamera();
    cameraFeedStatus = runtime.getState().cameraLabel ? `live / ${runtime.getState().cameraLabel}` : `error / ${runtime.getState().cameraError ?? "unavailable"}`;
  }
  function showDialog(name: ScannerDialogExampleName) {
    const overrides = name === "custom" ? { title: dialogTitle, body: dialogBody } : undefined;
    void examples.showDialog(name, overrides).then((action) => { dialogOutput = `resolved action / ${action}`; });
  }
  function saveGuide() {
    const url = URL.createObjectURL(new Blob([guide], { type: "text/markdown;charset=utf-8" }));
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = "SEEK-QR-IMPLEMENTATION.md";
    anchor.click();
    URL.revokeObjectURL(url);
  }
</script>

<aside id="panel" class="panel">
  <h1>Svelte scanner control wall<small>shared core modules / Svelte state bridge / parity laboratory</small></h1>

  <section class="grp">
    <h2>Scanner lifecycle</h2>
    <div class="btns">
      <button onclick={() => runtime.open()}>Open</button><button onclick={() => runtime.close()}>Close</button>
      <button onclick={() => runtime.pause()}>Pause</button><button onclick={() => runtime.resume()}>Resume</button>
      <button onclick={onRecreate}>Destroy + recreate</button>
      <button onclick={() => runtime.setInputLocked(true)}>Lock input</button><button onclick={() => runtime.setInputLocked(false)}>Unlock input</button>
    </div>
  </section>

  <section class="grp">
    <h2>Preview device</h2>
    <div class="seg" id="device-controls">
      {#each ["phone", "tablet", "web"] as value}
        <button aria-pressed={device === value} onclick={() => { device = value; onDevice(value); }}>{value === "web" ? "Web / host" : value[0]!.toUpperCase() + value.slice(1)}</button>
      {/each}
    </div>
    <div class="seg" id="orientation-controls">
      {#each ["portrait", "landscape"] as value}
        <button aria-pressed={orientation === value} onclick={() => { orientation = value; onOrientation(value); }}>{value[0]!.toUpperCase() + value.slice(1)}</button>
      {/each}
    </div>
    <label class="check"><input type="checkbox" onchange={(event) => onSafeArea(event.currentTarget.checked)} /> Simulate safe areas</label>
  </section>

  <section class="grp">
    <h2>Synthetic scanning</h2>
    <textarea bind:value={payload} rows="3" spellcheck="false"></textarea>
    <div class="btns"><button class="primary" onclick={emit}>Emit through real result path</button></div>
    <div class="preset-grid">
      <button onclick={() => { payload = "QR-7"; }}>Short</button>
      <button onclick={() => { payload = "https://example.test/scanner/integration?mode=long&source=svelte"; }}>Long URL</button>
      <button onclick={() => { payload = "雪 / λ / 📷"; }}>Unicode</button>
      <button onclick={() => { payload = "   padded payload   "; }}>Whitespace</button>
      <button onclick={() => { payload = ""; }}>Empty</button>
      <button onclick={() => void Promise.all(Array.from({ length: 5 }, (_, rapidIndex) => runtime.emitSynthetic(payload, { rapidIndex })))}>Rapid duplicates</button>
    </div>
  </section>

  <section class="grp">
    <h2>Status and results</h2>
    <input bind:value={statusText} />
    <div class="preset-grid">
      {#each ["neutral", "pending", "found", "unmatched", "success", "warning", "error"] as tone}
        <button onclick={() => runtime.setStatus({ tone: tone as StatusTone, text: statusText })}>{tone}</button>
      {/each}
      <button onclick={() => runtime.setStatus(null)}>Clear</button>
    </div>
    <div class="btns">
      <button onclick={() => runtime.setTargeting(true).setStatus({ tone: "pending", text: "Targeting mode controlled by host" })}>Targeting on</button>
      <button onclick={() => runtime.setTargeting(false).setStatus({ tone: "neutral", text: "Targeting cancelled by host" })}>Cancel targeting</button>
      <button onclick={() => runtime.dismissResult()}>Dismiss result</button>
    </div>
  </section>

  <section class="grp">
    <h2>Dialogs</h2>
    <input bind:value={dialogTitle} /><textarea bind:value={dialogBody} rows="2"></textarea>
    <div class="preset-grid">
      <button onclick={() => showDialog("warning")}>Generic warning</button><button onclick={() => showDialog("confirm-warning")}>Confirmation warning</button>
      <button onclick={() => showDialog("confirm")}>Confirmation</button><button onclick={() => showDialog("destructive")}>Destructive delete</button>
      <button onclick={() => showDialog("overwrite")}>Duplicate / overwrite</button><button onclick={() => showDialog("reassign")}>Reassignment</button>
      <button onclick={() => showDialog("blocked")}>Blocked action</button><button onclick={() => showDialog("error")}>Single-action error</button>
      <button onclick={() => showDialog("custom")}>Use editable copy</button>
    </div>
    <output class="readout">{dialogOutput}</output>
  </section>

  <section class="grp integration-examples">
    <h2>Accepted reference UI states</h2>
    <p>Every neutral state drives the real shared Svelte scanner surface. Host-looking operations remain inert.</p>
    <div class="preset-grid">
      {#each Object.keys(examples.states) as name}
        <button onclick={() => examples.states[name as ScannerExampleName]()}>{({ idle: "Idle camera", hold: "Hold / live preview", "lookup-success": "Known QR + jump", "lookup-miss": "Unknown QR", assign: "Assign prompt", rewrite: "Rewrite prompt", replace: "Overwrite prompt", conflict: "QRQT conflict", stale: "Stale warning", retired: "Retired code", blocked: "Permanent tombstone", "camera-error": "Camera error" } as Record<string, string>)[name]}</button>
      {/each}
    </div>
  </section>

  <section class="grp">
    <h2>Camera and live scanning</h2>
    <p class="camera-help">Allow camera access, then press and hold over a QR code in the preview. Release to commit.</p>
    <div class="btns"><button class="primary" onclick={startCamera}>Start / retry camera</button><button onclick={() => { runtime.stopCamera(); cameraFeedStatus = "stopped"; }}>Stop camera</button><button onclick={enumerate}>Enumerate cameras</button><button onclick={() => runtime.resetRoi()}>Reset ROI</button></div>
    <select onchange={(event) => { if (event.currentTarget.value) void runtime.selectCamera(event.currentTarget.value); }}>
      <option value="">{cameras.length ? "Select a camera" : "No enumerated camera"}</option>
      {#each cameras as camera, index}<option value={camera.deviceId}>{camera.label || `Camera ${index + 1}`}</option>{/each}
    </select>
    <div class="preset-grid">
      {#each Object.entries(cameraSimulationExamples) as [name, simulation]}
        <button onclick={() => runtime.setStatus(simulation)}>{name.replaceAll("-", " ")}</button>
      {/each}
    </div>
    <div class="state-pair"><span>Feed</span><output>{cameraFeedStatus}</output></div>
    <div class="state-pair"><span>ROI</span><output>x {scannerState.roi.x.toFixed(0)} / y {scannerState.roi.y.toFixed(0)} / {scannerState.roi.size.toFixed(0)}px</output></div>
  </section>

  <StateInspector state={scannerState} {events} onClear={onClearEvents} />

  <section class="grp">
    <h2>Live theme variables</h2>
    <label>Accent<input type="color" value="#c6a8ff" oninput={(event) => onTheme("--qrs-accent", event.currentTarget.value)} /></label>
    <label>Scanner background<input type="color" value="#04020c" oninput={(event) => onTheme("--qrs-bg", event.currentTarget.value)} /></label>
    <label>Result success<input type="color" value="#7fe3d4" oninput={(event) => onTheme("--qrs-success", event.currentTarget.value)} /></label>
    <label>Zone size<input type="text" value="4.95rem" oninput={(event) => onTheme("--qrs-zone-size", event.currentTarget.value)} /></label>
  </section>

  <footer class="guide-footer">
    <p><b>Canonical source:</b> <code>docs/IMPLEMENTATION.md</code></p>
    <a class="surface-link" href="../skeleton/">Open functional Svelte skeleton</a>
    <button class="save-guide" onclick={saveGuide}>
      <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3h13l3 3v15H4z M7 3v6h9V3 M7 14h10v7H7z" /></svg>
      Save Guide
    </button>
  </footer>
</aside>
