<script lang="ts">
  import { untrack } from "svelte";
  import type { ScannerState } from "../../src/core/types";
  import { createSvelteScannerRuntime, type SvelteScannerRuntime } from "../src/runtime/scanner-runtime";
  import ControlWall from "./components/ControlWall.svelte";
  import PreviewDevice from "./components/PreviewDevice.svelte";

  let { runtimeFactory }: { runtimeFactory?: () => SvelteScannerRuntime<unknown> } = $props();
  const factory = untrack(() => runtimeFactory ?? (() => createSvelteScannerRuntime<unknown>({
    camera: { autoStart: true, facingMode: "environment", idealWidth: 1920, idealHeight: 1080, allowSwitching: true },
    historyLimit: 25,
  })));
  let runtime = $state(factory());
  let scannerState = $state<Readonly<ScannerState<unknown>>>(untrack(() => runtime.getState()));
  let events = $state<{ time: string; type: string; detail: string }[]>([]);
  let device = $state("phone");
  let orientation = $state("portrait");
  let safeArea = $state(false);
  let theme = $state<Record<string, string>>({});

  const printable = (value: unknown) => {
    if (value === undefined) return "";
    try { return JSON.stringify(value); } catch { return String(value); }
  };

  $effect(() => {
    const current = runtime;
    const unsubscribe = current.subscribeState((value) => { scannerState = value; });
    const listeners = ["scanstart", "scanend", "scanpreview", "scanresult", "roichange", "dialogaction", "cameraerror", "action", "close"].map((type) => {
      const listener = (event: Event) => {
        const detail = "detail" in event ? (event as CustomEvent).detail : undefined;
        events = [{ time: new Date().toISOString().slice(11, 23), type, detail: printable(detail) }, ...events].slice(0, 80);
      };
      current.addEventListener(type, listener);
      return [type, listener] as const;
    });
    return () => {
      unsubscribe();
      for (const [type, listener] of listeners) current.removeEventListener(type, listener);
    };
  });

  function recreate() {
    runtime.destroy();
    runtime = factory();
    events = [{ time: new Date().toISOString().slice(11, 23), type: "instance-recreated", detail: "" }, ...events];
  }
</script>

<main id="lab" class="lab" data-device={device} data-orientation={orientation} data-safe-area={safeArea}>
  <div class="terminal-wall" aria-hidden="true">
    <div class="terminal-wall__ghost terminal-wall__ghost--one">SEEK_QR :: SVELTE_SURFACE :: PARITY_LAB</div>
    <div class="terminal-wall__ghost terminal-wall__ghost--two">ROI / FOCUS / EXPOSURE / ZOOM / DECODE</div>
    <div class="terminal-wall__grid"></div>
  </div>
  <PreviewDevice {runtime} badge={`INSTANCE / ${scannerState.lifecycle.toUpperCase()}${scannerState.inputLocked ? " / LOCKED" : ""}`} {theme} />
  <ControlWall
    {runtime}
    {scannerState}
    {events}
    onRecreate={recreate}
    onDevice={(value) => { device = value; requestAnimationFrame(() => runtime.resetRoi()); }}
    onOrientation={(value) => { orientation = value; requestAnimationFrame(() => runtime.resetRoi()); }}
    onSafeArea={(value) => { safeArea = value; requestAnimationFrame(() => runtime.resetRoi()); }}
    onTheme={(name, value) => { theme = { ...theme, [name]: value }; }}
    onClearEvents={() => { events = []; }}
  />
</main>
